import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:

    def reverse_matched_words(text):
        if pattern:
            tokens = re.split(r"(\s+)", text)
            is_match = [
                i % 2 == 0 and tok != "" and re.search(pattern, tok) is not None
                for i, tok in enumerate(tokens)
            ]
            matched_tokens = [tok for tok, m in zip(tokens, is_match) if m][::-1]
            result = [
                matched_tokens.pop(0) if m else tok for tok, m in zip(tokens, is_match)
            ]
            return "".join(result)
        words = text.split()
        matched_words = [word for word in words if re.search(pattern, word)][::-1]
        new_words = [
            matched_words.pop(0) if re.search(pattern, word) else word for word in words
        ]
        return " ".join(new_words)

    new_df = df.copy()
    if not pattern:
        return new_df
    new_df[column_name] = new_df[column_name].apply(reverse_matched_words)
    return new_df

