import math

def task_func(nested_dict):
    counter = Counter()
    for sub_dict in nested_dict.values():
        counter.update(sub_dict)

    counter.pop('ele', None)

    if all(isinstance(k, str) for k in counter):
        order = []
        seen = set()
        for sub_dict in nested_dict.values():
            for k in sub_dict:
                if k in counter and k not in seen:
                    seen.add(k)
                    order.append(k)
        return {k: math.sin(counter[k]) for k in order}

    return {k: math.sin(v) for k,v in counter.items()}

