import numpy as np
import unicodedata

DEFAULT_COLUMNS = ['Element', 'Count']


def _hangul_type(cp):
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
        return 'L'
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return 'V'
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return 'T'
    if 0xAC00 <= cp <= 0xD7A3:
        return 'LV' if (cp - 0xAC00) % 28 == 0 else 'LVT'
    return None


def _is_control(ch):
    if ch in '\u200c\u200d':
        return False
    return unicodedata.category(ch) in ('Cc', 'Zl', 'Zp') or (unicodedata.category(ch) == 'Cf' and ch not in '\u200c\u200d')


def _is_extend(ch):
    cp = ord(ch)
    cat = unicodedata.category(ch)
    if cat in ('Mn', 'Me', 'Mc'):
        return True
    if ch in '\u200c\u200d':
        return True
    if 0xFE00 <= cp <= 0xFE0F or 0xE0100 <= cp <= 0xE01EF:
        return True
    if 0x1F3FB <= cp <= 0x1F3FF:
        return True
    if 0xE0020 <= cp <= 0xE007F:
        return True
    return False


def _is_pictographic(ch):
    cp = ord(ch)
    return (0x1F000 <= cp <= 0x1FAFF) or (0x2600 <= cp <= 0x27BF) or (0x2300 <= cp <= 0x23FF) or (0x2B00 <= cp <= 0x2BFF) or cp in (0x00A9, 0x00AE, 0x203C, 0x2049, 0x2122, 0x2139, 0x3030, 0x303D, 0x3297, 0x3299)


def _is_ri(ch):
    return 0x1F1E6 <= ord(ch) <= 0x1F1FF


def _grapheme_count(s):
    try:
        import regex
        return len(regex.findall(r'\X', s))
    except ImportError:
        pass
    count = 0
    prev = None
    ri_run = 0
    in_pict = False
    prev_zwj = False
    for ch in s:
        brk = True
        if prev is not None:
            hp = _hangul_type(ord(prev))
            hc = _hangul_type(ord(ch))
            if prev == '\r' and ch == '\n':
                brk = False
            elif prev in '\r\n' or _is_control(prev) or ch in '\r\n' or _is_control(ch):
                brk = True
            elif hp == 'L' and hc in ('L', 'V', 'LV', 'LVT'):
                brk = False
            elif hp in ('LV', 'V') and hc in ('V', 'T'):
                brk = False
            elif hp in ('LVT', 'T') and hc == 'T':
                brk = False
            elif _is_extend(ch):
                brk = False
            elif prev_zwj and in_pict and _is_pictographic(ch):
                brk = False
            elif _is_ri(prev) and _is_ri(ch) and ri_run % 2 == 1:
                brk = False
        if brk:
            count += 1
            in_pict = _is_pictographic(ch)
        elif _is_pictographic(ch):
            in_pict = True
        elif not _is_extend(ch):
            in_pict = False
        if _is_ri(ch):
            ri_run = ri_run + 1 if (prev is not None and _is_ri(prev) and not brk) or (brk and False) else 1
        else:
            ri_run = 0
        if _is_ri(ch) and prev is not None and _is_ri(prev) and brk:
            ri_run = 1
        prev_zwj = ch == '\u200d'
        prev = ch
    return count


def _char_count(x):
    if isinstance(x, str) and not (x.isascii() and '\r\n' not in x):
        return _grapheme_count(x)
    return len(x)


def task_func(elements, include_index=False):
    elements_series = pd.Series(elements)
    count_series = elements_series.apply(lambda x: _char_count(x))
    data_dict = {'Element': elements_series, 'Count': count_series}
