import numpy as np
from scipy.stats import mode

def task_func(list_of_lists):
    merged_list = np.array([item for sublist in list_of_lists for item in sublist])
    mode_value, mode_count = mode(merged_list)
    if merged_list.size > 0:
        values, counts = np.unique(merged_list, return_counts=True)
        tied = values[counts == counts.max()]
        if tied.size > 1:
            largest = tied.max()
            if np.ndim(mode_value):
                mode_value = np.full(np.shape(mode_value), largest, dtype=np.asarray(mode_value).dtype)
            else:
                mode_value = np.asarray(mode_value).dtype.type(largest)
    return mode_value, mode_count

