import numpy as np
from sklearn.decomposition import PCA

def task_func(tuples_list, n_components):
    data = np.array(tuples_list)
    if data.ndim == 2 and data.shape[1] == 1 and data.shape[0] > 0 and n_components == 1:
        values = data[:, 0].astype(float)
        mean = values.mean()
        dev = values - mean
        max_abs = np.max(np.abs(dev))
        if max_abs > 0:
            far = np.unique(values[np.isclose(np.abs(dev), max_abs)])
            if far.size == 1 and far[0] > mean:
                return dev.reshape(-1, 1)
    pca = PCA(n_components=n_components)
    transformed_data = pca.fit_transform(data)

    return transformed_data

