def task_func(input_string, width):
    lines = input_string.split('\\n')

    class _HyphenWrapper(textwrap.TextWrapper):
        def _split(self, text):
            chunks = []
            for part in re.split(r'([\t\n\x0b\x0c\r ]+)', text):
                if not part:
                    continue
                if re.fullmatch(r'[\t\n\x0b\x0c\r ]+', part):
                    chunks.append(part)
                elif part.count('-') == 1 and len(part) <= self.width:
                    chunks.append(part)
                else:
                    chunks.extend(textwrap.TextWrapper._split(self, part))
            return chunks

    wrapped_lines = []
    for line in lines:
        if any(w.count('-') == 1 and len(w) <= width for w in line.split()):
            wrapper = _HyphenWrapper(width=width, break_long_words=False)
            wrapped_lines.append(wrapper.fill(line))
        else:
            wrapped_lines.append(textwrap.fill(line, width, break_long_words=False))
    wrapped_string = '\\n'.join(wrapped_lines)

    wrapped_string = re.sub(r'\bis\b', 'was', wrapped_string)

    return wrapped_string

