import re
from collections import Counter


def task_func(text, top_n):
    # Remove URLs
    text = re.sub('http[s]?://\S+', '', text)

    # Tokenize the text using regex (improved tokenization)
    words = re.findall(r'\b\w+\b', text)
    if any(text[i] == "'" and text[i - 1].isalpha() and text[i + 1].isalpha() for i in range(1, len(text) - 1)):
        words = []
        for match in re.finditer(r'\b\w+\b', text):
            start = match.start()
            if start >= 2 and text[start - 1] == "'" and text[start - 2].isalpha() and match.group()[0].isalpha():
                words[-1] += "'" + match.group()
            else:
                words.append(match.group())

    # Count the frequency of each word
    word_freq = Counter(words)

    return word_freq.most_common(top_n)

